contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        address user1 = address(0x1);
        address user2 = address(0x2);

        vm.deal(user1, 1 ether);
        vm.deal(user2, 0 ether);

        vm.prank(user1);
        c.seedMarket{value: 0}(10 ether);

        vm.prank(user1);
        c.getFreeKilo();

        vm.warp(block.timestamp + 86400);

        vm.deal(address(c), 1 ether);
        vm.prank(user1);
        c.buyDrugs{value: 0.1 ether}();

        uint256 user1Drugs = c.getMyDrugs();


        c = new EtherCartel();
        vm.prank(user1);
        c.seedMarket{value: 0}(1);

        vm.prank(user1);
        c.getFreeKilo();

        vm.warp(block.timestamp + 1);

        vm.prank(user1);
        c.collectDrugs(user2);

        assertTrue(c.marketDrugs() == 31, "marketDrugs should be 31 in reference");
